/*
 * `library.json` for the deploy, from the TypeScript that defines it.
 *
 * The manifest is generated by `src/app/libraryManifest.ts` out of the
 * library table and the refused-construct list. Those are TypeScript and the
 * webpack configuration is not, so this loads them the way a test runner
 * would: each module is transpiled on its own (types erased, nothing
 * checked - `npm run typecheck` does that) and evaluated with a `require`
 * that resolves the module's relative imports to further `.ts` files. Nothing
 * is registered with Node's own loader, so the webpack process is left as it
 * was found.
 *
 * `webpack.config.deploy.js` emits the result as an asset, so it lands in
 * whatever output directory is in effect; run directly, this prints it.
 */
const fs = require('fs');
const path = require('path');
const ts = require('typescript');

const ENTRY = path.resolve(__dirname, '..', 'src', 'app', 'libraryManifest.ts');

const resolveModule = (from, request) => {
  const base = path.resolve(path.dirname(from), request);
  for (const candidate of [`${base}.ts`, path.join(base, 'index.ts'), base]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
      return candidate;
    }
  }
  throw new Error(`cannot resolve ${request} from ${from}`);
};

/**
 * `{ text, files }`: the manifest as the deploy writes it, and every source
 * file it was read from, for the compilation to watch.
 */
function generateLibraryManifest() {
  const loaded = new Map();
  const load = (file) => {
    const cached = loaded.get(file);
    if (typeof cached !== 'undefined') {
      return cached.exports;
    }
    const module = { exports: {} };
    loaded.set(file, module);
    if (file.endsWith('.json')) {
      module.exports = JSON.parse(fs.readFileSync(file, 'utf8'));
      return module.exports;
    }
    const { outputText } = ts.transpileModule(fs.readFileSync(file, 'utf8'), {
      fileName: file,
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
      },
    });
    const localRequire = (request) =>
      request.startsWith('.')
        ? load(resolveModule(file, request))
        : require(request);
    new Function(
      'exports',
      'require',
      'module',
      '__filename',
      '__dirname',
      outputText
    )(module.exports, localRequire, module, file, path.dirname(file));
    return module.exports;
  };
  const { libraryManifestText } = load(ENTRY);
  return { text: libraryManifestText(), files: Array.from(loaded.keys()) };
}

module.exports = { generateLibraryManifest };

if (require.main === module) {
  process.stdout.write(generateLibraryManifest().text);
}
